import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { reportComment } from "../handlers/reportComment";
import type { ApiError } from "../runtime/client";
import type { ReportCommentRequest } from "../types/ReportCommentRequest";
import type { SpacePartition } from "../types/SpacePartition";
import type { SpacePostCommentTargetEntityType } from "../types/SpacePostCommentTargetEntityType";
import type { SpacePostEntityType } from "../types/SpacePostEntityType";

type Data = Awaited<ReturnType<typeof reportComment>>;
type Vars = { spaceId: SpacePartition; discussionSk: SpacePostEntityType; commentSk: SpacePostCommentTargetEntityType; req: ReportCommentRequest };

export function useReportComment(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => reportComment(vars.spaceId, vars.discussionSk, vars.commentSk, vars.req),
    ...options,
  });
}
